#!/bin/bash
# Kompletná oprava Prisma problému

cd /srv/EarningsTable && echo "═══════════════════════════════════════════════════════════" && echo "OPRAVA PRISMA PROBLÉMU" && echo "═══════════════════════════════════════════════════════════" && echo "" && echo "1. Zastavenie earnings-cron:" && systemctl stop earnings-cron && echo "" && echo "2. Prisma generate v modules/database:" && cd modules/database && npx prisma generate 2>&1 | tail -20 && echo "" && echo "3. Kontrola Prisma client:" && ls -la node_modules/.prisma/client/index.d.ts 2>&1 | head -3 && echo "" && echo "4. Prisma generate v modules/shared (ak existuje):" && cd ../shared && if [ -f "package.json" ]; then npx prisma generate 2>&1 | tail -10; else echo "modules/shared nemá package.json"; fi && echo "" && echo "5. Kontrola node_modules v modules/cron:" && cd ../cron && ls -la node_modules/@prisma/client 2>&1 | head -3 && echo "" && echo "6. Spustenie earnings-cron:" && cd /srv/EarningsTable && systemctl start earnings-cron && sleep 8 && echo "" && echo "7. Status service:" && systemctl status earnings-cron --no-pager -l | head -30 && echo "" && echo "8. Posledných 40 riadkov logov:" && journalctl -u earnings-cron -n 40 --no-pager | tail -25

